/* cppi::51f269bc8a1593f1d97efc8c2476a895e187937ffbf6d1f2dca984ba74a19de3 */
SELECT TRIM(currency_code) currency_code, ROUND(spot_rate,5) spot_rate, business_date
FROM market.msci_daily_fx_rates where business_date = date '2025-05-27'

