from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-04' and end_date = '2025-04-04')
and start_date = '2025-04-04' and end_date = '2025-04-04'
